    # Compute the maximum energy for each prefix of the necklace
    for i in range(2, len(beads) + 1):
        prefix_max[i] = max(prefix_max[i - 1], prefix_max[i - 2] + beads[i - 1] * beads[i - 2])
    # Compute the maximum energy for each suffix of the necklace
    for i in range(len(beads) - 1, 0, -1):
        suffix_max[i] = max(suffix_max[i + 1], suffix_max[i + 2] + beads[i] * beads[i + 1])
    # Compute the maximum energy for the entire necklace by combining the prefix and suffix maxima
    return max(prefix_max[len(beads)], suffix_max[1])
