    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    inorder_length = len(inorder)
    postorder_length = len(postorder)

    def traverse(inorder_start, inorder_end, postorder_start, postorder_end):
        if inorder_start > inorder_end or postorder_start > postorder_end:
            return ''
        if inorder_start == inorder_end:
            return inorder[inorder_start]
        root = postorder[postorder_end]
        inorder_root_index = inorder_idx[root]
        left_tree_size = inorder_root_index - inorder_start
        right_tree_size = inorder_end - inorder_root_ index
        left_subtree = traverse(inorder_start, inorder_root_index - 1, postorder_start, postorder_start + left_tree_size - 1)
        right_subtree = traverse(inorder_root_index + 1, inorder_end, postorder_end - right_tree_size, postorder_end - 1)
        return left_subtree + root + right_subtree

    return traverse(0, inorder_length - 1, 0, postorder_length - 1)
