    if n == 1:
        return 2

    all_moves = set()
    for i in range(2 ** n):
        for j in range(n):
            if i & (1 << j):
                num_moves = j + 1
                break

        for k in range(n - 1, -1, -1):
            if not i & (1 << k):
                num_moves += k + 1
                break

        all_moves.add(num_moves)

    return min(all_moves)

